import { txnOptions } from './routingConfig';

// Generate a random transaction with diverse attributes
export const generateTransaction = (index) => {
  const amount = txnOptions.amounts[Math.floor(Math.random() * txnOptions.amounts.length)];
  const cardNetwork = txnOptions.cardNetworks[Math.floor(Math.random() * txnOptions.cardNetworks.length)];
  const currency = txnOptions.currencies[Math.floor(Math.random() * txnOptions.currencies.length)];
  const riskScore = txnOptions.riskScores[Math.floor(Math.random() * txnOptions.riskScores.length)];

  // Generate card number based on network
  const cardPrefixes = {
    visa: ['4'],
    mastercard: ['5', '2'],
    amex: ['3'],
    discover: ['6'],
  };

  const prefix = cardPrefixes[cardNetwork][0];
  const cardNumber = `${prefix}${Math.random().toString().slice(2, 17)}`.slice(0, 16);

  return {
    id: `txn_${Date.now()}_${index}`,
    amount,
    cardNetwork,
    currency,
    riskScore,
    cardNumber: `****${cardNumber.slice(-4)}`,
    timestamp: Date.now(),
    // Derived attributes for display
    amountDisplay: amount < 100 ? `$${amount}` : `$${amount.toLocaleString()}`,
    riskLevel: riskScore > 70 ? 'High' : riskScore > 40 ? 'Medium' : 'Low',
  };
};

// Generate a batch of transactions
export const generateTransactionBatch = (count) => {
  return Array.from({ length: count }, (_, i) => generateTransaction(i));
};

// Simulate the routing decision process
export const simulateRouting = (txn, psps, rules) => {
  const steps = [];

  // Step 1: Eligibility Analysis
  const eligiblePsps = [...psps];
  steps.push({
    step: 1,
    name: 'Eligibility Analysis',
    description: 'Shortlisted eligible PSPs from pre-configured list',
    inputPsps: psps.map(p => ({ ...p })),
    outputPsps: eligiblePsps.map(p => ({ ...p })),
    rules: [],
  });

  // Step 2: Static Rule Filtering
  let filteredPsps = [...eligiblePsps];
  const activeStaticRules = rules.filter(r => r.type === 'static' && r.active);

  activeStaticRules.forEach(rule => {
    const beforeCount = filteredPsps.length;
    filteredPsps = rule.condition(txn, filteredPsps);
    const afterCount = filteredPsps.length;

    if (beforeCount !== afterCount) {
      steps[0].rules.push({
        rule: rule.name,
        removed: beforeCount - afterCount,
      });
    }
  });

  // Sort remaining PSPs by default preference (auth rate)
  filteredPsps.sort((a, b) => b.authRate - a.authRate);
  const selectedPsp = filteredPsps[0];

  steps.push({
    step: 2,
    name: 'Filtering PSPs',
    description: selectedPsp 
      ? `Selected ${selectedPsp.name} as the optimal processor through pre-configured rules`
      : 'No eligible PSPs found',
    selectedPsp: selectedPsp ? { ...selectedPsp } : null,
    availablePsps: filteredPsps.map(p => ({ ...p })),
  });

  // Step 3: Dynamic Override Check
  let finalPsp = selectedPsp;
  let overrideReason = null;
  let wasOverridden = false;

  if (selectedPsp) {
    const activeDynamicRules = rules.filter(r => r.type === 'dynamic' && r.active);

    for (const rule of activeDynamicRules) {
      const result = rule.check(selectedPsp, psps, { totalProcessed: 0 });
      if (result.override) {
        finalPsp = result.newPsp;
        overrideReason = result.reason;
        wasOverridden = true;
        break;
      }
    }
  }

  steps.push({
    step: 3,
    name: 'Ranking based on real-time data',
    description: wasOverridden
      ? `${finalPsp.name} selected due to ${overrideReason}`
      : finalPsp
      ? `${finalPsp.name} confirmed as optimal choice`
      : 'No PSP available',
    originalPsp: selectedPsp ? { ...selectedPsp } : null,
    finalPsp: finalPsp ? { ...finalPsp } : null,
    wasOverridden,
    overrideReason,
  });

  // Simulate success/failure
  const success = finalPsp ? Math.random() < finalPsp.currentAuthRate : false;

  return {
    txn,
    steps,
    selectedPsp: finalPsp,
    originalPsp: selectedPsp,
    wasOverridden,
    overrideReason,
    success,
    cost: finalPsp ? txn.amount * finalPsp.costPerTxn : 0,
    latency: finalPsp ? finalPsp.currentLatency : 0,
  };
};

// Update PSP statistics after each transaction
export const updatePspStats = (psps, pspId, success) => {
  return psps.map(psp => {
    if (psp.id === pspId) {
      const newVolume = psp.currentVolume + 1;
      const currentSuccesses = psp.currentAuthRate * psp.currentVolume;
      const newSuccesses = success ? currentSuccesses + 1 : currentSuccesses;
      const newAuthRate = newVolume > 0 ? newSuccesses / newVolume : psp.authRate;

      // Add some randomness to latency (simulate real-time fluctuations)
      const latencyVariance = (Math.random() - 0.5) * 100;
      const newLatency = Math.max(200, psp.avgLatency + latencyVariance);

      return {
        ...psp,
        currentVolume: newVolume,
        currentAuthRate: newAuthRate,
        currentLatency: Math.round(newLatency),
      };
    }
    return psp;
  });
};

import React, { useState } from 'react';
import { X, Loader2 } from 'lucide-react';
import API_BASE_URL from '../config';

const DebugCredentialsModal = ({ initialCredentials, onSave, onCancel }) => {
  const [credentials, setCredentials] = useState(initialCredentials || {
    publishableKey: '',
    secretKey: '',
    profileId: '',
    merchantId: '',
  });
  const [errors, setErrors] = useState({});
  const [isValidating, setIsValidating] = useState(false);
  const [validationError, setValidationError] = useState(null);

  const isEditing = !!initialCredentials;

  const handleChange = (field, value) => {
    setCredentials(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: null }));
    }
    if (validationError) {
      setValidationError(null);
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!credentials.publishableKey.trim()) newErrors.publishableKey = 'Publishable Key is required';
    if (!credentials.secretKey.trim()) newErrors.secretKey = 'Secret Key is required';
    if (!credentials.profileId.trim()) newErrors.profileId = 'Profile ID is required';
    if (!credentials.merchantId.trim()) newErrors.merchantId = 'Merchant ID is required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const validateCredentials = async () => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    try {
      const response = await fetch(`${API_BASE_URL}/api/create-customer`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Debug-Mode': 'true',
          'X-Publishable-Key': credentials.publishableKey,
          'X-Secret-Key': credentials.secretKey,
          'X-Profile-Id': credentials.profileId,
          'X-Merchant-Id': credentials.merchantId,
        },
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error?.message || 'Invalid credentials');
      }

      return true;
    } catch (error) {
      clearTimeout(timeoutId);
      if (error.name === 'AbortError') {
        throw new Error('Validation timed out. Please check your credentials and try again.');
      }
      throw new Error(error.message || 'Failed to validate credentials');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsValidating(true);
    setValidationError(null);

    try {
      await validateCredentials();
      onSave(credentials);
    } catch (error) {
      setValidationError(error.message);
    } finally {
      setIsValidating(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl max-w-md w-full p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            Debug Mode Credentials
          </h2>
          <button
            onClick={onCancel}
            className="p-1 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-500"
          >
            <X size={20} />
          </button>
        </div>

        <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
          Enter your sandbox credentials to use Debug Mode. These will be stored locally in your browser.
        </p>

        {validationError && (
          <div className="mb-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
            <p className="text-sm text-red-600 dark:text-red-400">
              <strong>Validation Failed:</strong> {validationError}
            </p>
            <p className="text-xs text-red-500 dark:text-red-400 mt-1">
              Please check your credentials and try again. Make sure you're using sandbox credentials.
            </p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Publishable Key
            </label>
            <input
              type="text"
              value={credentials.publishableKey}
              onChange={(e) => handleChange('publishableKey', e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
              placeholder="pk_snd_..."
            />
            {errors.publishableKey && (
              <p className="text-xs text-red-500 mt-1">{errors.publishableKey}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Secret Key
            </label>
            <input
              type="password"
              value={credentials.secretKey}
              onChange={(e) => handleChange('secretKey', e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
              placeholder="snd_..."
            />
            {errors.secretKey && (
              <p className="text-xs text-red-500 mt-1">{errors.secretKey}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Profile ID
            </label>
            <input
              type="text"
              value={credentials.profileId}
              onChange={(e) => handleChange('profileId', e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
              placeholder="pro_..."
            />
            {errors.profileId && (
              <p className="text-xs text-red-500 mt-1">{errors.profileId}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Merchant ID
            </label>
            <input
              type="text"
              value={credentials.merchantId}
              onChange={(e) => handleChange('merchantId', e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
              placeholder="merchant_..."
            />
            {errors.merchantId && (
              <p className="text-xs text-red-500 mt-1">{errors.merchantId}</p>
            )}
          </div>

          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 text-sm font-medium"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-2 bg-primary hover:bg-primary-dark text-white rounded-lg text-sm font-medium"
            >
              {isEditing ? 'Update & Reload' : 'Save & Enable Debug Mode'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default DebugCredentialsModal;

import React, { useState } from 'react';
import { useRecoilValue, useSetRecoilState } from 'recoil';
import { apiResponseState, demoModeState, debugCredentialsState } from '../utils/atoms';
import { makeAuthenticatedRequest } from '../utils/api';

// Static card data
const CARD_DATA = {
  card_number: '4111111111111111',
  card_exp_month: '03',
  card_exp_year: '30',
  card_cvc: '737',
  card_holder_name: 'John Doe',
};

const RelayIncrementalAuth = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [step, setStep] = useState(1);
  const [adyenTransactionId, setAdyenTransactionId] = useState(null);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [additionalAmount, setAdditionalAmount] = useState('5000');
  const [hasClicked, setHasClicked] = useState(false);
  const setApiResponse = useSetRecoilState(apiResponseState);
  const mode = useRecoilValue(demoModeState);
  const debugCreds = useRecoilValue(debugCredentialsState);

  const handleStep1 = async () => {
    setHasClicked(true);
    setIsLoading(true);
    setError(null);

    try {
      // Step 1: Create Adyen Authorization (authorize only)
      const authData = await makeAuthenticatedRequest('/api/adyen/authorize', {
        method: 'POST',
        body: JSON.stringify({
          amount: 10000,
          card_data: CARD_DATA,
        }),
      }, mode, debugCreds);

      if (authData.error) {
        throw new Error(authData.error.message || 'Adyen authorization failed');
      }

      setAdyenTransactionId(authData.adyenTransactionId);
      setStep(2);
      setHasClicked(false);

      // Update API response panel
      setApiResponse({
        steps: [
          {
            title: 'Step 1: Adyen Direct Authorization',
            request: {
              method: 'POST',
              url: '/pal/servlet/Payment/v68/authorise',
              body: {
                amount: { currency: 'USD', value: 10000 },
                merchantAccount: 'JuspayDEECOM',
                paymentMethod: {
                  type: 'scheme',
                  number: CARD_DATA.card_number,
                  expiryMonth: CARD_DATA.card_exp_month,
                  expiryYear: CARD_DATA.card_exp_year,
                  cvc: CARD_DATA.card_cvc,
                  holderName: CARD_DATA.card_holder_name,
                },
              },
            },
            response: {
              adyen_transaction_id: authData.adyenTransactionId,
              resultCode: authData.adyenResponse.resultCode,
              authCode: authData.adyenResponse.authCode,
            },
          },
        ],
        currentStep: 1,
      });

    } catch (err) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStep2 = async () => {
    setHasClicked(true);
    setIsLoading(true);
    setError(null);

    try {
      // Step 2: Relay Incremental Authorization using Adyen Transaction ID
      const relayData = await makeAuthenticatedRequest('/api/relay/incremental-auth', {
        method: 'POST',
        body: JSON.stringify({
          adyen_transaction_id: adyenTransactionId,
          additional_amount: parseInt(additionalAmount, 10),
          currency: 'USD',
        }),
      }, mode, debugCreds);

      if (relayData.error) {
        throw new Error(relayData.error.message || 'Relay incremental auth failed');
      }

      setResult(relayData);
      setStep(3);

      // Update API response panel
      setApiResponse((prev) => ({
        steps: [
          ...prev.steps,
          {
            title: 'Step 2: Hyperswitch Relay - Incremental Authorization',
            request: {
              method: 'POST',
              url: '/relay',
              headers: {
                'X-Profile-Id': 'pro_N6tqlbSOXjTN42Go3dgL',
              },
              body: {
                connector_id: 'mca_zaNgRbqSDoFFEyDDamoj',
                connector_resource_id: adyenTransactionId,
                type: 'incremental_authorization',
                data: {
                  amount: parseInt(additionalAmount, 10),
                },
              },
            },
            response: {
              relay_id: relayData.relayId,
              status: relayData.status,
              type: relayData.type,
              adyen_transaction_id: relayData.adyenTransactionId,
            },
          },
        ],
        currentStep: 2,
      }));

    } catch (err) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-800 rounded-lg p-4">
        <h3 className="font-medium text-indigo-900 dark:text-indigo-300 mb-2">
          Relay - Incremental Authorization
        </h3>
        <p className="text-sm text-indigo-700 dark:text-indigo-400">
          Two-step flow: Adyen Authorization → Relay Incremental Auth
          <br />
          <strong>Card:</strong> {CARD_DATA.card_number} | Exp: {CARD_DATA.card_exp_month}/{CARD_DATA.card_exp_year}
        </p>
      </div>

      {step === 1 && (
        <button
          onClick={handleStep1}
          disabled={isLoading || hasClicked}
          className="w-full bg-primary hover:bg-primary-dark text-white font-medium py-3 px-6 rounded-lg transition-colors disabled:opacity-50"
        >
{isLoading ? 'Processing...' : 'Step 1: Adyen Authorization ($100)'}
        </button>
      )}

      {step === 2 && (
        <div className="space-y-4">
          <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg">
            <p className="text-sm text-yellow-800 dark:text-yellow-300">
              <strong>Adyen Transaction ID (Key Resource):</strong>
            </p>
            <p className="text-lg font-mono text-yellow-700 dark:text-yellow-400 mt-1 break-all">
              {adyenTransactionId}
            </p>
            <p className="text-xs text-yellow-600 dark:text-yellow-400 mt-2">
              This Transaction ID is used in the Relay API call to Hyperswitch
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Additional Amount (cents)
            </label>
            <input
              type="number"
              value={additionalAmount}
              onChange={(e) => setAdditionalAmount(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
              placeholder="Enter additional amount in cents"
            />
            <p className="text-xs text-gray-500 mt-1">
              Current: ${parseInt(additionalAmount) / 100}
            </p>
          </div>

          <button
            onClick={handleStep2}
            disabled={isLoading || hasClicked}
            className="w-full bg-primary hover:bg-primary-dark text-white font-medium py-3 px-6 rounded-lg transition-colors disabled:opacity-50"
          >
{isLoading ? 'Processing...' : 'Step 2: Relay Incremental Auth via Hyperswitch'}
          </button>
        </div>
      )}

      {step === 3 && result && (
        <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg">
          <h4 className="font-medium text-green-900 dark:text-green-300 mb-2">Incremental Authorization Successful!</h4>
          <div className="text-sm text-green-700 dark:text-green-400 space-y-1">
            <p><strong>Relay ID:</strong> {result.relayId}</p>
            <p><strong>Status:</strong> {result.status}</p>
            <p><strong>Adyen Transaction ID:</strong> {result.adyenTransactionId}</p>
            <p><strong>Additional Amount:</strong> ${parseInt(additionalAmount) / 100}</p>
          </div>
        </div>
      )}

      {error && (
        <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
          <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
        </div>
      )}
    </div>
  );
};

export default RelayIncrementalAuth;

import React from 'react';
import { CheckCircle, XCircle, ArrowRight, Zap, Filter, TrendingUp } from 'lucide-react';

// PSP Avatar with Juspay Blue
const PspAvatar = ({ psp, size = 'md', isSelected, isEliminated }) => {
  const sizeClasses = {
    sm: 'w-10 h-10 text-sm',
    md: 'w-12 h-12 text-base',
    lg: 'w-16 h-16 text-lg',
  };

  return (
    <div
      className={`${sizeClasses[size]} rounded-full flex items-center justify-center font-bold transition-all duration-500 ${
        isEliminated 
          ? 'bg-gray-300 text-gray-500' 
          : isSelected 
          ? 'bg-[#0066FF] text-white ring-4 ring-[#E6F0FF]' 
          : 'bg-[#0066FF] text-white'
      }`}
    >
      {psp?.shortName || '?'}
    </div>
  );
};

// Status Badge with Juspay colors
