      AuthenticationType: true,
      Currency: true,
      Country: true,
      CardNetwork: true,
      CardBin: true,
    },
    numberOfBatches: DEFAULT_NUMBER_OF_BATCHES,
    batchSize: DEFAULT_BATCH_SIZE,
    ...initialValues,
  });

  const [expandedConnectors, setExpandedConnectors] = useState({});
