                    </div>
                  </div>
                );
              })
            ) : (
              <p className="text-center text-gray-500 dark:text-gray-400 py-4">
                No connector data available. Run a simulation.
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

