  switch (flow.id) {
    case 'zero_setup':
      return {
        ...base,
        amount: 0,
        setup_future_usage: 'off_session',
        mandate_data: {
          customer_acceptance: { acceptance_type: 'offline' },
          mandate_type: {
            multi_use: {
              amount: 10000,
