            },
          },
        },
      };
    case 'setup_and_charge':
      return {
        ...base,
        amount: 10000,
        setup_future_usage: 'off_session',
        mandate_data: {
          customer_acceptance: { acceptance_type: 'offline' },
          mandate_type: {
            multi_use: {
              amount: 10000,
              currency: 'USD',
            },
          },
        },
      };
    case 'recurring_charge':
      return {
